'use strict';

/* =====================================================================
 * Lexique Python — alimente les infobulles du code et la page #/lexique
 * ---------------------------------------------------------------------
 * Clé = le mot tel qu'il apparaît dans le code :
 *   - "def", "print", "Annotated"…        identifiant ou mot-clé
 *   - ".model_dump"                       méthode/attribut (après un point)
 *   - "@dataclass", "@router"             décorateur (premier segment)
 *   - "->", "...", "*", "**", "|"         symboles
 *   - "f-string", "docstring"             littéraux spéciaux
 *   - concept: true                       entrée de lexique non détectée dans le code
 * ===================================================================== */

const G = (cat, def, java, extra = {}) => ({ cat, def, java, ...extra });

